/* suppress HMC on /mac-mini/ */
.page-overview-mac-mini .section-contrast .section-header-cta-item-choose { display: none; }

/* suppress HMC on /business/ */
.page-business .section-router .card-shop .help-me-choose-link { display: none; }
.page-business .section-faq [data-accordion-item="accordion-item-faq-choose-mac"] { display: none; }

/* suppress HMC on /business/small-business/ */
.page-small-business .section-router .help-me-choose-tile { display: none; }

